import{_ as t,o as s,c as o,a3 as a}from"./chunks/framework.BveOjhN0.js";const h=JSON.parse('{"title":"Jobs Introduction","description":"","frontmatter":{"title":"Jobs Introduction"},"headers":[],"relativePath":"00.docs/020.basic-features/060.tasks/010.jobs-intro.md","filePath":"00.docs/020.basic-features/060.tasks/010.jobs-intro.md","lastUpdated":1783502384000}'),r={name:"00.docs/020.basic-features/060.tasks/010.jobs-intro.md"};function n(i,e,c,d,l,p){return s(),o("div",null,[...e[0]||(e[0]=[a('<h3 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h3><p>The EE framework&#39;s main process is single-threaded. The advantage is high development efficiency, but when dealing with compute-intensive business, developers need to learn to use <strong>child processes</strong> or encapsulate renderer process script execution, and also need to implement communication and encryption features; this is quite difficult for developers.</p><p>The framework provides a pre-packaged <strong>task module</strong> that makes it easy for developers to meet their requirements.</p><h3 id="business-directory" tabindex="-1">Business Directory <a class="header-anchor" href="#business-directory" aria-label="Permalink to &quot;Business Directory&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./electron/jobs</span></span></code></pre></div><p>The jobs mode creates child processes via Node.js. During packaging, they are excluded from the bundle and have a separate directory structure.</p><p><strong>Important</strong></p><ul><li>Code in jobs files should not import code from controllers or services. It is recommended to write standalone code in the jobs/ directory</li><li>Jobs cannot call Electron APIs (Electron officially does not support this). It is recommended to send messages to the main process and let the main process call them</li></ul>',8)])])}const m=t(r,[["render",n]]);export{h as __pageData,m as default};
